; nmi_port_3F2 — запис у регістр керування дисководами (DOR, Digital Output Register).
; Біти вибору дисковода 0–1 перетворюються на позиційний код (дисковод 0 → біт0, 1 → біт1), біт 3
; (дозвіл IRQ/DMA) ставиться примусово; результат — у 0040:00B9 і в апаратний регістр F000:0601.
; При знятті скидання (біт 2: 0→1) емулюється переривання 765 після скидання: чекаємо на IRQ НГМД і викликаємо INT 0Eh.
; ----------------------------------------------------------------------------------------------
nmi_port_3F2:    ; посилання: 04D9
F400:0A3A  51              push   cx                          ; зберігаємо регістри перерваної програми, що використовуються нижче
F400:0A3B  52              push   dx                          ; зберігаємо DX
F400:0A3C  57              push   di                          ; зберігаємо DI
F400:0A3D  56              push   si                          ; зберігаємо SI
F400:0A3E  1E              push   ds                          ; зберігаємо DS
F400:0A3F  BB4000          mov    bx, 40h                     ; сегмент 0040h
F400:0A42  8EDB            mov    ds, bx                      ; DS = область даних BIOS
F400:0A44  26A00004        mov    al, byte es:[400h]          ; AL = записаний байт DOR (парний порт → клямка F000:0400)
F400:0A48  8A26B900        mov    ah, byte [0B9h]             ; AH = попереднє значення DOR (тіньовий регістр 0040:00B9)
F400:0A4C  F6C404          test   ah, 4                       ; контролер уже було виведено зі скидання (біт 2 = /RESET)?
F400:0A4F  7540            jne    loc_0A91                    ; так → просто оновити регістр керування
F400:0A51  A804            test   al, 4                       ; нове значення знімає скидання?
F400:0A53  743C            je     loc_0A91                    ; ні (лишаємося в скиданні) → просто оновити регістр
F400:0A55  8AC8            mov    cl, al                      ; перехід скидання→робота: CL = біт 0 номера дисковода (підтримуються 2 дисководи)
F400:0A57  80E101          and    cl, 1                       ; лише біт 0
F400:0A5A  B401            mov    ah, 1                       ; AH = 1
F400:0A5C  D2E4            shl    ah, cl                      ; AH = 1 << дисковод → позиційний код вибору (01 або 02)
F400:0A5E  24FC            and    al, 0FCh                    ; очищаємо поле вибору дисковода
F400:0A60  0AC4            or     al, ah                      ; вставляємо позиційний код вибору
F400:0A62  0C08            or     al, 8                       ; біт 3 — дозвіл переривання НГМД (прапорець «немає псевдо-DMA обміну»)
F400:0A64  A2B900          mov    byte [0B9h], al             ; запам'ятовуємо в тіньовому DOR 0040:00B9
F400:0A67  26A20106        mov    byte es:[601h], al          ; в апаратний регістр керування дисководами F000:0601 (мотори, вибір, скидання)
F400:0A6B  C606BA0000      mov    byte [0BAh], 0              ; 0040:00BA — стан приймання команди 765: 0 = чекаємо на перший байт нової команди

; ----------------------------------------------------------------------------------------------
; Очікування переривання від 765 (після скидання або після команди) і його доставка через INT 0Eh.
; Опитує біт 15 слова F000:0200 (запит IRQ НГМД) приблизно 2x65536 разів; за тайм-аутом — мовчки виходить.
; ----------------------------------------------------------------------------------------------
loc_0A70:    ; посилання: 0B37 0BA9
F400:0A70  FB              sti                                ; дозволяємо переривання (всередині NMI) — нехай ідуть таймер/клавіатура
F400:0A71  B302            mov    bl, 2                       ; BL = 2 — зовнішній лічильник тайм-ауту
F400:0A73  33C9            xor    cx, cx                      ; CX = 0 → 65536 ітерацій внутрішнього циклу

loc_0A75:    ; посилання: 0A7D 0A81
F400:0A75  26A10002        mov    ax, word es:[200h]          ; читаємо слово стану переривань F000:0200
F400:0A79  D0E4            shl    ah, 1                       ; біт 15 (запит переривання НГМД) → CF
F400:0A7B  720C            jb     loc_0A89                    ; є переривання від 765 → викликати обробник
F400:0A7D  E2F6            loop   loc_0A75                    ; опитування з тайм-аутом
F400:0A7F  FECB            dec    bl                          ; зовнішній лічильник
F400:0A81  75F2            jne    loc_0A75                    ; ще коло
F400:0A83  1F              pop    ds                          ; тайм-аут: переривання не було — відновлюємо регістри й виходимо
F400:0A84  5E              pop    si                          ; відновлюємо SI
F400:0A85  5F              pop    di                          ; відновлюємо DI
F400:0A86  5A              pop    dx                          ; відновлюємо DX
F400:0A87  59              pop    cx                          ; відновлюємо CX
F400:0A88  C3              ret                                ; повернення в NMI_HANDLER

loc_0A89:    ; посилання: 0A7B
F400:0A89  CD0E            int    0Eh                         ; емулюємо IRQ6: викликаємо обробник НГМД INT 0Eh (ставить біт 7 у 0040:003E)
F400:0A8B  1F              pop    ds                          ; відновлюємо DS
F400:0A8C  5E              pop    si                          ; відновлюємо SI
F400:0A8D  5F              pop    di                          ; відновлюємо DI
F400:0A8E  5A              pop    dx                          ; відновлюємо DX
F400:0A8F  59              pop    cx                          ; відновлюємо CX
F400:0A90  C3              ret                                ; повернення

; ----------------------------------------------------------------------------------------------
; Звичайний запис DOR (без зняття скидання): те саме перетворення вибору дисковода, без очікування переривання
; ----------------------------------------------------------------------------------------------
loc_0A91:    ; посилання: 0A4F 0A53
F400:0A91  8AC8            mov    cl, al                      ; CL = номер дисковода (біт 0)
F400:0A93  80E101          and    cl, 1                       ; лише біт 0
F400:0A96  B401            mov    ah, 1                       ; AH = 1
F400:0A98  D2E4            shl    ah, cl                      ; позиційний код вибору дисковода
F400:0A9A  24FC            and    al, 0FCh                    ; очищаємо біти 0–1
F400:0A9C  0AC4            or     al, ah                      ; вставляємо код вибору
F400:0A9E  0C08            or     al, 8                       ; біт 3 — дозвіл IRQ НГМД
F400:0AA0  A2B900          mov    byte [0B9h], al             ; тіньовий DOR 0040:00B9
F400:0AA3  26A20106        mov    byte es:[601h], al          ; апаратний регістр керування дисководами F000:0601
F400:0AA7  1F              pop    ds                          ; відновлюємо DS
F400:0AA8  5E              pop    si                          ; відновлюємо SI
F400:0AA9  5F              pop    di                          ; відновлюємо DI
F400:0AAA  5A              pop    dx                          ; відновлюємо DX
F400:0AAB  59              pop    cx                          ; відновлюємо CX
F400:0AAC  C3              ret                                ; повернення

; ----------------------------------------------------------------------------------------------
; nmi_port_3F4 — читання головного регістра стану 765 (MSR). Реальний 765: F000:0600 = MSR
; ----------------------------------------------------------------------------------------------
nmi_port_3F4:    ; посилання: 04DB
F400:0AAD  7507            jne    loc_0AB6                    ; запис у 3F4 (на XT немає) — ігноруємо
F400:0AAF  26A00006        mov    al, byte es:[600h]          ; читаємо MSR реального 765 (F000:0600)
F400:0AB3  884600          mov    byte [bp], al               ; результат IN → збережений AL

loc_0AB6:    ; посилання: 0AAD
F400:0AB6  C3              ret                                ; повернення

; ----------------------------------------------------------------------------------------------
; nmi_port_3F5 — регістр даних 765. Читання — прямо з F000:0602.
