F000:E07D  9F              lahf                               ; читаємо прапорці назад в AH
F000:E07E  B105            mov    cl, 5                       ; зсув на 5
F000:E080  D2EC            shr    ah, cl                      ; біт 4 (AF) → CF
F000:E082  733F            jae    loc_E0C3                    ; AF має бути 1
F000:E084  B040            mov    al, 40h                     ; AL = 40h
F000:E086  D0E0            shl    al, 1                       ; 40h<<1 = 80h → переповнення, OF=1
F000:E088  7139            jno    loc_E0C3                    ; OF має бути 1
F000:E08A  32E4            xor    ah, ah                      ; AH = 0
F000:E08C  9E              sahf                               ; скидаємо всі прапорці
F000:E08D  7634            jbe    loc_E0C3                    ; CF і ZF мають бути 0
F000:E08F  7832            js     loc_E0C3                    ; SF має бути 0
F000:E091  7A30            jp     loc_E0C3                    ; PF має бути 0
F000:E093  9F              lahf                               ; прапорці → AH
F000:E094  B105            mov    cl, 5                       ; зсув на 5
F000:E096  D2EC            shr    ah, cl                      ; AF → CF
F000:E098  7229            jb     loc_E0C3                    ; AF має бути 0
F000:E09A  D0E4            shl    ah, 1                       ; зсув нуля — OF=0
F000:E09C  7025            jo     loc_E0C3                    ; OF має бути 0

; ----------------------------------------------------------------------------------------------
; Тест регістрів: значення FFFFh, потім 0000h проганяється через усі сегментні й загальні регістри
; ----------------------------------------------------------------------------------------------
