F000:E0B8  33C7            xor    ax, di                      ; перший прохід: DI має збігтися з FFFFh (AX стане 0)
F000:E0BA  7507            jne    loc_E0C3                    ; не збіглося → помилка процесора
F000:E0BC  F8              clc                                ; CF=0 — другий прохід
F000:E0BD  EBE3            jmp    loc_E0A2                    ; повторюємо з AX = 0

loc_E0BF:    ; посилання: E0B6
F000:E0BF  0BC7            or     ax, di                      ; другий прохід: DI має бути 0
F000:E0C1  7402            je     loc_E0C5                    ; усе правильно → продовження POST

