; Прохід 1 (уперед): кожен байт має бути FFh, записується 00h; прохід 2 (назад): кожен байт 00h.
; Вихід: ZF=1 — справно; ZF=0 — збій, AL = XOR (маска збійних бітів), DI = зміщення збійного байта.
; Викликається й до ініціалізації стека (через mov sp,E070h / jmp) — тоді RET бере адресу з ПЗП.
; ----------------------------------------------------------------------------------------------
loc_E46D:    ; посилання: E12A E46A
F000:E46D  FC              cld                                ; Напрямок — вперед
F000:E46E  2BFF            sub    di, di                      ; DI = 0 — початок блока
F000:E470  8BF7            mov    si, di                      ; SI = 0
F000:E472  8BD9            mov    bx, cx                      ; BX = довжина в словах…
F000:E474  D1E3            shl    bx, 1                       ; …×2 = довжина в байтах
F000:E476  B4FF            mov    ah, 0FFh                    ; AH = FFh — очікуване значення в першому проході

loc_E478:    ; посилання: E48E
F000:E478  8BF7            mov    si, di                      ; SI = DI — читаємо там само, куди пишемо
F000:E47A  8BCB            mov    cx, bx                      ; CX = довжина блока в байтах

loc_E47C:    ; посилання: E484
F000:E47C  AC              lodsb  al, byte [si]               ; Читаємо байт
F000:E47D  32C4            xor    al, ah                      ; Порівнюємо з очікуваним (XOR дає маску помилкових бітів)
F000:E47F  750F            jne    loc_E490                    ; Не збіглося — вихід із ZF=0
F000:E481  32C0            xor    al, al                      ; AL = 0 — нове значення
F000:E483  AA              stosb  byte es:[di], al            ; Записуємо 00h у перевірений байт
F000:E484  E2F6            loop   loc_E47C                    ; Увесь блок
F000:E486  22E4            and    ah, ah                      ; Це був перший прохід (AH=FFh)?
F000:E488  7406            je     loc_E490                    ; Другий прохід завершено (AH=0) — вихід із ZF=1
F000:E48A  8AE0            mov    ah, al                      ; AH = 0 — у другому проході очікуємо нулі
F000:E48C  4F              dec    di                          ; DI → останній байт блока
F000:E48D  FD              std                                ; Напрямок — назад
F000:E48E  EBE8            jmp    loc_E478                    ; Другий прохід (від кінця до початку)

