F000:EFBC  FEC0            inc    al                          ; AL = EOT+1 — «наступний» після останнього

loc_EFBE:    ; посилання: EFB2
F000:EFBE  2AC1            sub    al, cl                      ; AL = номер наступного сектора − початковий сектор = кількість переданих секторів
F000:EFC0  C3              ret                                ; Повернення
