F000:FEFB  53FF            dw     DUMMY_IRET                  ; INT 0Ch — заглушка IRET (COM1; ймовірно, перевизначається драйвером)
F000:FEFD  53FF            dw     DUMMY_IRET                  ; INT 0Dh — заглушка IRET (IRQ5, в XT — вінчестер)
F000:FEFF  57EF            dw     INT0E_DISKETTE_IRQ          ; INT 0Eh — переривання дисковода, F000:EF57
F000:FF01  0004            dw     0400h                       ; INT 0Fh — спільний обробник апаратних переривань F400:0400 (сегмент F400 ставиться в E1AD)

